-- One-time production seed for Phase 1.
-- Fill in the two real email addresses before running this file.

BEGIN;
SET search_path TO our_adventures, public;

-- Seed allowlisted users idempotently.
ON CONFLICT (email)
DO UPDATE SET display_name = EXCLUDED.display_name;

-- Seed baseline activities once. Abort if activities already exist.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM activities LIMIT 1) THEN
    RAISE EXCEPTION 'activities already exist; aborting baseline seed';
  END IF;
END
$$;


COMMIT;
